WITH exploded AS (SELECT id, service, log_ts, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, value), valid AS (SELECT *, DATEDIFF(CURRENT_DATE(), log_ts) / 7 AS weeks_since_log_ts FROM exploded WHERE status_code = 414), remaining_keys AS (SELECT id FROM valid EXCEPT ALL SELECT id FROM app_logs WHERE status_code BETWEEN 289 AND 383), kept_rows AS (SELECT s.* FROM valid s INNER JOIN remaining_keys k ON s.id = k.id), filtered AS (SELECT id, latency_ms, status_code, key, value, weeks_since_log_ts, ROUND(status_code / latency_ms, 2) AS status_code_per_latency_ms FROM kept_rows WHERE log_ts >= DATE '2025-06-01' AND key IS DISTINCT FROM 'version'), kept_keys AS (SELECT id FROM filtered INTERSECT ALL SELECT id FROM app_logs WHERE level = 'WARN'), verified AS (SELECT s.* FROM filtered s INNER JOIN kept_keys k ON s.id = k.id), base AS (SELECT *, CASE WHEN key IN ('region', 'trace') THEN 'Core' ELSE 'Other' END AS key_group, CASE WHEN status_code >= 413 THEN 'High' WHEN status_code >= 234 THEN 'Medium' ELSE 'Low' END AS status_code_band, COALESCE(key, 'NONE') AS key_clean FROM verified WHERE key IS NOT NULL AND weeks_since_log_ts < 73), metrics AS (SELECT *, CORR(latency_ms, status_code) OVER (PARTITION BY key) AS corr_latency_ms_status_code FROM base) SELECT *, MAX(status_code_per_latency_ms) OVER (PARTITION BY key) AS key_max_status_code_per_latency_ms, AVG(latency_ms) OVER (PARTITION BY key) AS key_avg_latency_ms, MIN(weeks_since_log_ts) OVER (PARTITION BY key) AS key_min_weeks_since_log_ts, MIN(status_code_per_latency_ms) OVER (PARTITION BY key) AS key_min_status_code_per_latency_ms, DENSE_RANK() OVER (PARTITION BY key ORDER BY latency_ms NULLS LAST) AS latency_ms_dense_rank FROM metrics;
